<?php
require_once __DIR__.'/auth.php'; require_once __DIR__.'/../config/database.php';
function require_admin_page(): void { require_login(); require_role('Admin'); }
function require_user_page(): void { require_login(); require_role('User'); }
function get_laporan(int $id, bool $lock=false): array|false { global $pdo; $sql='SELECT l.*,u.nama pelapor,k.nama_kategori,lo.nama_gedung,lo.lantai,lo.ruang,i.jumlah_total,i.jumlah_baik,i.jumlah_rusak FROM laporan l JOIN users u ON u.id_user=l.id_user JOIN inventaris_fasilitas i ON i.id_inventaris=l.id_inventaris JOIN kategori_fasilitas k ON k.id_kategori=i.id_kategori JOIN lokasi lo ON lo.id_lokasi=i.id_lokasi WHERE l.id_laporan=? AND l.deleted_at IS NULL'; if($lock)$sql.=' FOR UPDATE';$s=$pdo->prepare($sql);$s->execute([$id]);return $s->fetch(); }
function get_riwayat(int $id): array {global $pdo;$s=$pdo->prepare('SELECT r.*,u.nama pengubah FROM riwayat_status r JOIN users u ON u.id_user=r.id_pengubah WHERE r.id_laporan=? ORDER BY r.waktu_perubahan DESC,r.id_riwayat DESC');$s->execute([$id]);return $s->fetchAll();}
function add_history(int $id,int $user,?string $old,string $new,?string $note=null): void {global $pdo;$s=$pdo->prepare('INSERT INTO riwayat_status(id_laporan,id_pengubah,status_lama,status_baru,catatan) VALUES(?,?,?,?,?)');$s->execute([$id,$user,$old,$new,$note]);}
function render_empty(string $title,string $description,string $url,string $button): void {echo '<div class="sp-card sp-empty"><div class="sp-empty-icon">'.icon('file').'</div><h3>'.e($title).'</h3><p class="sp-muted">'.e($description).'</p><a class="btn sp-btn-primary" href="'.e(app_url($url)).'">'.e($button).' →</a></div>';}
function status_stepper(string $status): void {$steps=['Menunggu Verifikasi','Terverifikasi','Sedang Ditangani','Selesai'];if($status==='Ditolak'){echo '<div class="alert alert-danger">● Laporan Ditolak</div>';return;} $current=array_search($status,$steps,true);foreach($steps as $i=>$s){$done=$i<=$current;echo '<div class="sp-step '.($done?'done':'').'"><span class="sp-step-dot">'.($done?'✓':($i+1)).'</span><div><strong>'.e($s).'</strong>'.($i===$current?'<div class="sp-muted small">Status saat ini</div>':'').'</div></div>';}}
function validate_manual_inventory(int $id,int $baik,int $rusak): void {global $pdo;$s=$pdo->prepare('SELECT COALESCE(SUM(jumlah_unit),0) FROM laporan WHERE id_inventaris=? AND kondisi_diterapkan=1 AND deleted_at IS NULL');$s->execute([$id]);$applied=(int)$s->fetchColumn();if($rusak<$applied)throw new RuntimeException("Jumlah rusak tidak boleh kurang dari {$applied} unit yang sedang dihitung rusak oleh laporan terverifikasi.");}
